-- Iraqi administrative divisions. Data: OCHA COD-AB Iraq (CC BY-IGO), Wikidata (CC0); Kurdish name datasets and their licences: see DATA_LICENSE.md.
CREATE TABLE iraq_admin_divisions (
    code VARCHAR(16) NOT NULL PRIMARY KEY,
    level VARCHAR(16) NOT NULL,
    parent_code VARCHAR(16) NULL,
    name_ar VARCHAR(200) NOT NULL,
    name_en VARCHAR(200) NOT NULL,
    name_ku VARCHAR(200) NULL,
    lat DECIMAL(9, 6) NOT NULL,
    lng DECIMAL(9, 6) NOT NULL,
    area_sqkm DECIMAL(12, 2) NOT NULL,
    wikidata_id VARCHAR(16) NULL,
    iso_code VARCHAR(8) NULL,
    name_ku_source VARCHAR(16) NULL,
    kurdish_name_dataset VARCHAR(64) NULL,
    is_district_centre BOOLEAN NOT NULL,
    ocha_code VARCHAR(16) NULL,
    is_deprecated BOOLEAN NOT NULL,
    replaced_by VARCHAR(16) NULL
);

